function AdvisorPanel({ profile, onLogout }) {

  const [activeSection, setActiveSection] =
    useState("Mis interesados");

  const [menuOpen, setMenuOpen] = useState(false);

  const [leads, setLeads] = useState([]);

  const [leadHistories, setLeadHistories] = useState({});

  const [showFollowUp, setShowFollowUp] =
    useState(false);

  const [appointments, setAppointments] = useState([]);

  const [maintenancePlans, setMaintenancePlans] = useState({});

  const [appointmentHistories, setAppointmentHistories] = useState({});

  const [search, setSearch] = useState("");

  const [statusFilter, setStatusFilter] =
    useState("Todos");

  const [showNewLead, setShowNewLead] =
    useState(false);

  const [selectedLead, setSelectedLead] =
    useState(null);

  const [showEditLead, setShowEditLead] =
    useState(false);

  const [selectedAppointment, setSelectedAppointment] =
    useState(null);

  const [showNewAppointment, setShowNewAppointment] =
    useState(false);

  const [showEditAppointment, setShowEditAppointment] =
    useState(false);

  // ============================================================
  // SUPABASE — MIS INTERESADOS
  // La consulta depende de RLS: Supabase solo devuelve los leads
  // que pertenecen al asesor autenticado.
  // ============================================================
  useEffect(() => {
    let mounted = true;

    const loadLeads = async () => {
      if (!profile?.id || profile.role !== "asesor") return;

      const { data, error } = await supabase
        .from("leads")
        .select(
          "id, advisor_id, name, phone, occupation, address, status, observation, registered_at, last_contact_at, created_at, updated_at"
        )
        .order("registered_at", { ascending: false });

      if (error) {
        console.error("ERROR AL CARGAR INTERESADOS:", error);
        if (mounted) setLeads([]);
        return;
      }

      const mappedLeads = (data || []).map((lead) => ({
        id: lead.id,
        advisorId: lead.advisor_id,
        name: lead.name,
        phone: lead.phone,
        occupation: lead.occupation,
        address: lead.address,
        status: lead.status,
        observation: lead.observation || "",
        registered: lead.registered_at
          ? formatDateLabel(new Date(lead.registered_at))
          : "Sin fecha",
        lastContact: lead.last_contact_at
          ? formatDateLabel(new Date(lead.last_contact_at))
          : "Sin seguimiento",
        registeredAt: lead.registered_at,
        lastContactAt: lead.last_contact_at,
        createdAt: lead.created_at,
        updatedAt: lead.updated_at,
      }));

      if (mounted) {
        setLeads(mappedLeads);
      }
    };

    loadLeads();

    return () => {
      mounted = false;
    };
  }, [profile?.id, profile?.role]);

  // ============================================================
  // SUPABASE — AGENDA DEL ASESOR
  // RLS limita los resultados al asesor autenticado.
  // ============================================================
  useEffect(() => {
    let mounted = true;

    const loadAppointments = async () => {
      if (!profile?.id || profile.role !== "asesor") return;

      const { data, error } = await supabase
        .from("appointments")
        .select(
          "id, advisor_id, lead_id, type, appointment_date, start_time, end_time, location, notes, status, source, automation_type, automation_cycle_id, service_plan_id, created_at, updated_at"
        )
        .order("appointment_date", { ascending: true })
        .order("start_time", { ascending: true });

      if (error) {
        console.error("ERROR AL CARGAR CITAS DEL ASESOR:", error);
        if (mounted) setAppointments([]);
        return;
      }

      const mappedAppointments = (data || []).map((appointment) => {
        const selectedLead = leads.find(
          (lead) => String(lead.id) === String(appointment.lead_id)
        );

        return {
        id: appointment.id,
        advisorId: appointment.advisor_id,
        leadId: appointment.lead_id,
        type: appointment.type,
        date: appointment.appointment_date,
        time: appointment.start_time
          ? appointment.start_time.slice(0, 5)
          : "",
        endTime: appointment.end_time
          ? appointment.end_time.slice(0, 5)
          : "",
        client: selectedLead?.name || "",
        location: appointment.location || "",
        notes: appointment.notes || "",
        status: appointment.status,
        source: appointment.source,
        automationType: appointment.automation_type,
        automationCycleId: appointment.automation_cycle_id,
        servicePlanId: appointment.service_plan_id,
        createdAt: appointment.created_at,
        updatedAt: appointment.updated_at,
        };
      });

      if (mounted) {
        setAppointments(mappedAppointments);
        console.info(
          "CITAS DEL ASESOR CARGADAS DESDE SUPABASE:",
          mappedAppointments
        );
      }
    };

    loadAppointments();

    return () => {
      mounted = false;
    };
  }, [profile?.id, profile?.role, leads]);

  // ============================================================
  // SUPABASE — HISTORIAL DE SEGUIMIENTOS DEL INTERESADO
  // RLS limita los resultados al asesor autenticado.
  // ============================================================
  useEffect(() => {
    let mounted = true;

    const loadLeadFollowUps = async () => {
      if (!selectedLead?.id || profile?.role !== "asesor") return;

      const { data, error } = await supabase
        .from("lead_follow_ups")
        .select("id, lead_id, advisor_id, note, created_at, follow_up_type")
        .eq("lead_id", selectedLead.id)
        .order("created_at", { ascending: false });

      if (error) {
        console.error("ERROR AL CARGAR HISTORIAL DEL INTERESADO:", error);
        if (mounted) {
          setLeadHistories((current) => ({
            ...current,
            [selectedLead.id]: [],
          }));
        }
        return;
      }

      const mappedHistory = (data || []).map((followUp) => ({
        id: followUp.id,
        type: followUp.follow_up_type,
        text: followUp.note,
        date: followUp.created_at
          ? formatDateLabel(new Date(followUp.created_at))
          : "Sin fecha",
        time: followUp.created_at
          ? formatTimeLabel(new Date(followUp.created_at))
          : "",
        createdAt: followUp.created_at,
      }));

      if (mounted) {
        setLeadHistories((current) => ({
          ...current,
          [selectedLead.id]: mappedHistory,
        }));
      }
    };

    loadLeadFollowUps();

    return () => {
      mounted = false;
    };
  }, [selectedLead?.id, profile?.role]);

  const filteredLeads = useMemo(() => {
    const query = search.trim().toLowerCase();

    return leads.filter((lead) => {
      const matchesSearch =
        !query ||
        lead.name.toLowerCase().includes(query) ||
        lead.phone.includes(query) ||
        lead.occupation.toLowerCase().includes(query);

      const matchesStatus =
        statusFilter === "Todos" ||
        lead.status === statusFilter;

      return matchesSearch && matchesStatus;
    });
  }, [leads, search, statusFilter]);

  const handleNavigation = (section) => {
    setActiveSection(section);
    setMenuOpen(false);
  };

  const addLead = async (newLead) => {
    try {
      const { data, error } = await supabase.rpc(
        "create_lead_for_current_advisor",
        {
          p_name: newLead.name,
          p_phone: newLead.phone,
          p_occupation: newLead.occupation,
          p_address: newLead.address,
          p_observation: newLead.observation || null,
        }
      );

      if (error) {
        console.error("ERROR AL CREAR INTERESADO:", error);
        window.alert(error.message || "No se pudo registrar el interesado.");
        return;
      }

      const createdLead = data;

      if (!createdLead) {
        console.error("ERROR AL CREAR INTERESADO: Supabase no devolvió el registro creado.");
        window.alert("No se pudo confirmar el registro del interesado.");
        return;
      }

      const mappedLead = {
        id: createdLead.id,
        advisorId: createdLead.advisor_id,
        name: createdLead.name,
        phone: createdLead.phone,
        occupation: createdLead.occupation,
        address: createdLead.address,
        status: createdLead.status,
        observation: createdLead.observation || "",
        registered: createdLead.registered_at
          ? formatDateLabel(new Date(createdLead.registered_at))
          : "Sin fecha",
        lastContact: createdLead.last_contact_at
          ? formatDateLabel(new Date(createdLead.last_contact_at))
          : "Sin seguimiento",
        registeredAt: createdLead.registered_at,
        lastContactAt: createdLead.last_contact_at,
        createdAt: createdLead.created_at,
        updatedAt: createdLead.updated_at,
      };

      setLeads((current) => [mappedLead, ...current]);

      setLeadHistories((current) => ({
        ...current,
        [mappedLead.id]: [],
      }));

      setSelectedLead(mappedLead);
      setShowNewLead(false);
    } catch (error) {
      console.error("ERROR INESPERADO AL CREAR INTERESADO:", error);
      window.alert("Ocurrió un error al registrar el interesado.");
    }
  };

  const createMaintenanceAppointment = (lead, dateKey, reason = "") => {
    if (!lead) return null;

    const alreadyExists = appointments.some(
      (appointment) =>
        String(appointment.leadId) === String(lead.id) &&
        appointment.type === "Mantenimiento de equipo" &&
        appointment.date === dateKey &&
        appointment.status !== "Cancelada"
    );

    if (alreadyExists) return null;

    const maintenanceId = Date.now() + Math.floor(Math.random() * 1000);
    const appointment = {
      id: maintenanceId,
      leadId: lead.id,
      date: dateKey,
      time: "10:00",
      endTime: "11:00",
      client: lead.name,
      type: "Mantenimiento de equipo",
      status: "Pendiente",
      location: "Por definir",
      notes: `Mantenimiento de equipo de ${lead.name}.`,
      autoGeneratedForMaintenance: true,
      generatedReason: reason,
    };

    setAppointments((current) => [appointment, ...current]);
    setAppointmentHistories((current) => ({
      ...current,
      [maintenanceId]: [
        {
          id: maintenanceId + 1,
          date: formatDateLabel(new Date()),
          time: formatTimeLabel(new Date()),
          text: reason || `Mantenimiento programado para ${dateKey}.`,
        },
      ],
    }));
    return appointment;
  };

  const createTrainingAppointment = (lead, dateKey) => {
    if (!lead) return null;

    const alreadyExists = appointments.some(
      (appointment) =>
        String(appointment.leadId) === String(lead.id) &&
        appointment.type === "Capacitación" &&
        appointment.status !== "Cancelada"
    );

    if (alreadyExists) return null;

    const trainingId = Date.now() + Math.floor(Math.random() * 1000);
    const appointment = {
      id: trainingId,
      leadId: lead.id,
      date: dateKey,
      time: "10:00",
      endTime: "11:00",
      client: lead.name,
      type: "Capacitación",
      status: "Pendiente",
      location: "Por definir",
      notes: `Capacitación para ${lead.name} sobre el uso y cuidado del equipo adquirido.`,
      autoGeneratedForTrainingStatus: true,
    };

    setAppointments((current) => [appointment, ...current]);
    setAppointmentHistories((current) => ({
      ...current,
      [trainingId]: [
        {
          id: trainingId + 1,
          date: formatDateLabel(new Date()),
          time: formatTimeLabel(new Date()),
          text: `Capacitación generada automáticamente para ${dateKey}.`,
        },
      ],
    }));
    return appointment;
  };

  const updateLeadStatus = (leadId, status) => {
    const previousLead = leads.find((lead) => lead.id === leadId);
    if (!previousLead || previousLead.status === status) return;

    const now = new Date();
    const dateLabel = formatDateLabel(now);
    const timeLabel = formatTimeLabel(now);
    const todayKey = formatDateKey(now);
    const nextLead = { ...previousLead, status };

    setLeads((current) => current.map((lead) => lead.id === leadId ? nextLead : lead));

    if (status === "Pendiente de capacitación") {
      const trainingDate = addDaysToDateKey(todayKey, TRAINING_DAYS_AFTER_STATUS);
      createTrainingAppointment(nextLead, trainingDate);
    }

    if (status === "Mantenimiento") {
      const maintenanceDate = addMonthsToDateKey(todayKey, MAINTENANCE_MONTHS);
      createMaintenanceAppointment(
        nextLead,
        maintenanceDate,
        `Mantenimiento generado al cambiar manualmente el estado de ${nextLead.name} a "Mantenimiento".`
      );
      setMaintenancePlans((current) => ({
        ...current,
        [leadId]: {
          active: true,
          activatedDate: todayKey,
          nextDate: maintenanceDate,
        },
      }));
    }

    if (status !== "Mantenimiento") {
      setMaintenancePlans((current) => {
        if (!current[leadId]) return current;
        return {
          ...current,
          [leadId]: { ...current[leadId], active: false },
        };
      });
    }

    setSelectedLead(nextLead);
  };

  const updateLead = (leadId, updatedLead) => {
    const previousLead = leads.find(
      (lead) => lead.id === leadId
    );

    const now = new Date();
    const nextLead = {
      ...updatedLead,
      id: leadId,
    };

    setLeads((current) =>
      current.map((lead) =>
        lead.id === leadId ? nextLead : lead
      )
    );

    // El estado también puede cambiarse desde el formulario de actualización.
    // Mantiene las mismas automatizaciones manuales del cambio de estado.
    if (nextLead.status !== previousLead?.status) {
      if (nextLead.status === "Pendiente de capacitación") {
        const trainingDate = addDaysToDateKey(formatDateKey(now), TRAINING_DAYS_AFTER_STATUS);
        createTrainingAppointment(nextLead, trainingDate);
      }
      if (nextLead.status === "Mantenimiento") {
        const maintenanceDate = addMonthsToDateKey(formatDateKey(now), MAINTENANCE_MONTHS);
        createMaintenanceAppointment(
          nextLead,
          maintenanceDate,
          `Mantenimiento generado al cambiar manualmente el estado de ${nextLead.name} a "Mantenimiento".`
        );
        setMaintenancePlans((current) => ({
          ...current,
          [leadId]: { active: true, activatedDate: formatDateKey(now), nextDate: maintenanceDate },
        }));
      }
      if (nextLead.status !== "Mantenimiento") {
        setMaintenancePlans((current) => current[leadId]
          ? { ...current, [leadId]: { ...current[leadId], active: false } }
          : current
        );
      }
    }

    setSelectedLead(nextLead);
    setShowEditLead(false);
  };

  const addLeadFollowUp = async (leadId, followUp) => {
    const { data, error } = await supabase.rpc(
      "create_lead_follow_up_for_current_advisor",
      {
        p_lead_id: leadId,
        p_follow_up_type: followUp.type,
        p_note: followUp.text,
      }
    );

    if (error) {
      console.error("ERROR AL GUARDAR SEGUIMIENTO:", error);
      throw new Error(error.message || "No se pudo guardar el seguimiento.");
    }

    const created = Array.isArray(data) ? data[0] : data;

    if (!created) {
      throw new Error("Supabase no devolvió el seguimiento creado.");
    }

    const createdAt = created.created_at || new Date().toISOString();

    const entry = {
      id: created.id,
      type: created.follow_up_type,
      text: created.note,
      date: formatDateLabel(new Date(createdAt)),
      time: formatTimeLabel(new Date(createdAt)),
      createdAt,
    };

    setLeadHistories((current) => ({
      ...current,
      [leadId]: [entry, ...(current[leadId] || [])],
    }));

    setLeads((current) =>
      current.map((lead) =>
        lead.id === leadId
          ? {
              ...lead,
              lastContact: formatDateLabel(new Date(createdAt)),
              lastContactAt: createdAt,
              observation: created.note,
            }
          : lead
      )
    );

    setSelectedLead((current) =>
      current && current.id === leadId
        ? {
            ...current,
            lastContact: formatDateLabel(new Date(createdAt)),
            lastContactAt: createdAt,
            observation: created.note,
          }
        : current
    );

    setShowFollowUp(false);
  };

  const updateAppointmentStatus = (id, status) => {
    const previousAppointment = appointments.find((appointment) => appointment.id === id);
    if (!previousAppointment) return;

    setAppointments((current) => current.map((appointment) =>
      appointment.id === id ? { ...appointment, status } : appointment
    ));

    const lead = previousAppointment.leadId
      ? leads.find((item) => String(item.id) === String(previousAppointment.leadId))
      : null;
    const now = new Date();
    const completionDate = formatDateKey(now);
    const dateLabel = formatDateLabel(now);
    const timeLabel = formatTimeLabel(now);

    if (
      status === "Completada" &&
      previousAppointment.status !== "Completada" &&
      previousAppointment.type === "Capacitación" &&
      lead
    ) {
      const maintenanceDate = addMonthsToDateKey(completionDate, MAINTENANCE_MONTHS);
      const nextLead = {
        ...lead,
        status: "Mantenimiento",
        lastContact: `${dateLabel}, ${timeLabel}`,
        observation: `Capacitación completada. El cliente entra al ciclo de mantenimiento cada 3 meses.`,
      };

      setLeads((current) => current.map((item) => item.id === lead.id ? nextLead : item));
      setMaintenancePlans((current) => ({
        ...current,
        [lead.id]: { active: true, activatedDate: completionDate, nextDate: maintenanceDate },
      }));
      createMaintenanceAppointment(
        nextLead,
        maintenanceDate,
        `Primer mantenimiento generado automáticamente 3 meses después de completar la capacitación (${maintenanceDate}).`
      );
      setSelectedLead(nextLead);
    }

    if (
      status === "Completada" &&
      previousAppointment.status !== "Completada" &&
      previousAppointment.type === "Mantenimiento de equipo" &&
      lead
    ) {
      const plan = maintenancePlans[lead.id];
      if (plan?.active !== false) {
        const nextMaintenanceDate = addMonthsToDateKey(completionDate, MAINTENANCE_MONTHS);
        createMaintenanceAppointment(
          { ...lead, status: "Mantenimiento" },
          nextMaintenanceDate,
          `Siguiente mantenimiento generado automáticamente 3 meses después del mantenimiento realizado (${nextMaintenanceDate}).`
        );
        setMaintenancePlans((current) => ({
          ...current,
          [lead.id]: {
            ...(current[lead.id] || {}),
            active: true,
            nextDate: nextMaintenanceDate,
          },
        }));
        setLeads((current) => current.map((item) => item.id === lead.id
          ? { ...item, status: "Mantenimiento", lastContact: `${dateLabel}, ${timeLabel}`, observation: `Mantenimiento completado. Próximo mantenimiento programado para ${nextMaintenanceDate}.` }
          : item
        ));
        setSelectedLead((current) => current && current.id === lead.id
          ? { ...current, status: "Mantenimiento", lastContact: `${dateLabel}, ${timeLabel}`, observation: `Mantenimiento completado. Próximo mantenimiento programado para ${nextMaintenanceDate}.` }
          : current
        );
        setLeadHistories((current) => ({
          ...current,
          [lead.id]: [
            {
              id: Date.now() + 2,
              date: dateLabel,
              time: timeLabel,
              type: "Mantenimiento",
              text: `Mantenimiento completado. El siguiente quedó programado para ${nextMaintenanceDate}.`,
            },
            ...(current[lead.id] || []),
          ],
        }));
      }
    }

    setSelectedAppointment((current) => current && current.id === id ? { ...current, status } : current);
  };

  const pauseMaintenanceAutomation = (leadId) => {
    setMaintenancePlans((current) => ({
      ...current,
      [leadId]: {
        ...(current[leadId] || {}),
        active: false,
      },
    }));

    // Pausar la automatización cancela únicamente las citas de mantenimiento
    // futuras que fueron generadas automáticamente. Las citas creadas
    // manualmente permanecen intactas.
    setAppointments((current) => current.map((appointment) => {
      const isFutureMaintenance =
        String(appointment.leadId) === String(leadId) &&
        appointment.type === "Mantenimiento de equipo" &&
        appointment.autoGeneratedForMaintenance &&
        appointment.status === "Pendiente";

      return isFutureMaintenance
        ? { ...appointment, status: "Cancelada" }
        : appointment;
    }));
  };

  const reactivateMaintenanceAutomation = (leadId, activationDate) => {
    const lead = leads.find((item) => item.id === leadId);
    if (!lead || !activationDate) return;

    const nextDate = addMonthsToDateKey(activationDate, MAINTENANCE_MONTHS);
    setMaintenancePlans((current) => ({
      ...current,
      [leadId]: {
        active: true,
        activatedDate: activationDate,
        nextDate,
      },
    }));

    createMaintenanceAppointment(
      { ...lead, status: "Mantenimiento" },
      nextDate,
      `Automatización de mantenimiento reactivada el ${activationDate}. Próximo mantenimiento programado para ${nextDate}.`
    );
  };

  const updateAppointment = (id, updatedAppointment) => {
    const previousAppointment = appointments.find(
      (appointment) => appointment.id === id
    );

    const selectedLead = leads.find(
      (lead) => String(lead.id) === String(updatedAppointment.leadId)
    );

    const nextAppointment = {
      ...updatedAppointment,
      id,
      leadId: updatedAppointment.leadId || previousAppointment?.leadId,
      client: selectedLead?.name || updatedAppointment.client || previousAppointment?.client || "",
    };

    setAppointments((current) =>
      current.map((appointment) =>
        appointment.id === id
          ? nextAppointment
          : appointment
      )
    );

    if (nextAppointment.type === "Mantenimiento de equipo" && nextAppointment.leadId) {
      setMaintenancePlans((current) => current[nextAppointment.leadId]
        ? {
            ...current,
            [nextAppointment.leadId]: {
              ...current[nextAppointment.leadId],
              nextDate: nextAppointment.date,
            },
          }
        : current
      );
    }

    if (
      nextAppointment.notes?.trim() &&
      nextAppointment.notes.trim() !==
        previousAppointment?.notes?.trim()
    ) {
      const entry = {
        id: Date.now(),
        date: formatDateLabel(now),
        time: new Date().toLocaleTimeString("es-MX", {
          hour: "numeric",
          minute: "2-digit",
        }),
        text: nextAppointment.notes.trim(),
      };

      setAppointmentHistories((current) => ({
        ...current,
        [id]: [entry, ...(current[id] || [])],
      }));
    }

    setSelectedAppointment(nextAppointment);
    setShowEditAppointment(false);
  };

  const addAppointment = async (newAppointment) => {
    const selectedLead = leads.find(
      (lead) => String(lead.id) === String(newAppointment.leadId)
    );

    if (!selectedLead?.id || !selectedLead?.advisorId) {
      console.error(
        "ERROR AL GUARDAR CITA: no se encontró el interesado o su asesor."
      );
      window.alert("No se pudo identificar el interesado o el asesor de la cita.");
      return;
    }

    try {
      const { data, error } = await supabase
        .from("appointments")
        .insert({
          advisor_id: selectedLead.advisorId,
          lead_id: selectedLead.id,
          type: newAppointment.type,
          appointment_date: newAppointment.date,
          start_time: newAppointment.time || null,
          end_time: newAppointment.endTime || null,
          location: newAppointment.location || null,
          notes: newAppointment.notes?.trim() || null,
          status: newAppointment.status || "Pendiente",
        })
        .select(
          "id, advisor_id, lead_id, type, status, appointment_date, start_time, end_time, location, notes, source, automation_type, automation_cycle_id, service_plan_id, created_at, updated_at"
        )
        .single();

      if (error) {
        console.error("ERROR AL GUARDAR CITA EN SUPABASE:", error);
        window.alert(error.message || "No se pudo guardar la cita.");
        return;
      }

      if (!data) {
        console.error("ERROR AL GUARDAR CITA: Supabase no devolvió la cita creada.");
        window.alert("No se pudo confirmar la cita creada.");
        return;
      }

      const appointmentToAdd = {
        id: data.id,
        advisorId: data.advisor_id,
        leadId: data.lead_id,
        client: selectedLead.name,
        type: data.type,
        status: data.status,
        date: data.appointment_date,
        time: data.start_time || "",
        endTime: data.end_time || "",
        location: data.location || "",
        notes: data.notes || "",
        source: data.source,
        automationType: data.automation_type,
        automationCycleId: data.automation_cycle_id,
        servicePlanId: data.service_plan_id,
        createdAt: data.created_at,
        updatedAt: data.updated_at,
      };

      setAppointments((current) => [
        appointmentToAdd,
        ...current,
      ]);

      if (appointmentToAdd.type === "Mantenimiento de equipo") {
        setMaintenancePlans((current) => ({
          ...current,
          [selectedLead.id]: {
            ...(current[selectedLead.id] || {}),
            nextDate: appointmentToAdd.date,
          },
        }));
      }

      if (appointmentToAdd.notes?.trim()) {
        const now = new Date();

        setAppointmentHistories((current) => ({
          ...current,
          [appointmentToAdd.id]: [
            {
              id: `${appointmentToAdd.id}-initial-note`,
              date: formatDateLabel(now),
              time: formatTimeLabel(now),
              text: appointmentToAdd.notes.trim(),
            },
          ],
        }));
      }

      console.info("CITA CREADA EN SUPABASE:", data);
      setShowNewAppointment(false);
    } catch (error) {
      console.error("ERROR INESPERADO AL GUARDAR CITA:", error);
      window.alert("Ocurrió un error al guardar la cita.");
    }
  };

  return (
    <div className="app-shell">

      {/* =====================================================
          SIDEBAR
      ===================================================== */}

      <aside
        className={`sidebar ${
          menuOpen ? "sidebar-open" : ""
        }`}
      >

        <div className="sidebar-top">

          <div className="sidebar-brand">

            <div className="sidebar-logo">
              RP
            </div>

            <div className="sidebar-wordmark">
              <span>ROYAL</span>
              <strong>PRESTIGE</strong>
            </div>

          </div>

          <button
            className="mobile-close"
            onClick={() => setMenuOpen(false)}
            aria-label="Cerrar menú"
          >
            ×
          </button>

          <div className="advisor-profile">

            <div className="advisor-avatar">
              {getInitials(profile?.full_name || "Usuario")}
            </div>

            <div className="advisor-profile-text">
              <strong>{profile?.full_name || "Usuario"}</strong>
              <span>Asesor</span>
            </div>

          </div>

          <div className="sidebar-divider" />

          <nav className="sidebar-nav">

            <span className="nav-title">
              MENÚ PRINCIPAL
            </span>

            {navigation.map((item) => (
              <button
                key={item.name}
                className={`nav-item ${
                  activeSection === item.name
                    ? "active"
                    : ""
                }`}
                onClick={() =>
                  handleNavigation(item.name)
                }
              >
                <span className="nav-icon">
                  {item.icon}
                </span>

                <span>
                  {item.name}
                </span>
              </button>
            ))}

          </nav>

        </div>

        <div className="sidebar-bottom">

          <button className="nav-item secondary">
            <span className="nav-icon">
              ⚙
            </span>

            <span>
              Configuración
            </span>
          </button>

          <button
            className="nav-item logout"
            type="button"
            onClick={onLogout}
          >
            <span className="nav-icon">
              ↪
            </span>

            <span>
              Cerrar sesión
            </span>
          </button>

        </div>

      </aside>

      {menuOpen && (
        <div
          className="mobile-overlay"
          onClick={() => setMenuOpen(false)}
        />
      )}

      {/* =====================================================
          CONTENIDO
      ===================================================== */}

      <main className="main-content">

        {/* HEADER MOBILE */}

        <header className="mobile-header">

          <button
            className="hamburger"
            onClick={() => setMenuOpen(true)}
            aria-label="Abrir menú"
          >
            <span />
            <span />
            <span />
          </button>

          <div className="mobile-brand">
            <span>ROYAL</span>
            <strong>PRESTIGE</strong>
          </div>

          <div className="mobile-user">
            {getInitials(profile?.full_name || "Usuario")}
          </div>

        </header>

        {/* HEADER DESKTOP */}

        <header className="topbar">

          <div>

            <span className="topbar-label">
              PLATAFORMA COMERCIAL
            </span>

            <h1>
              {activeSection}
            </h1>

          </div>

          <div className="topbar-right">

            <button
              className="notification-button"
              aria-label="Notificaciones"
            >
              <span>♢</span>
              <i />
            </button>

            <div className="topbar-user">

              <div className="topbar-avatar">
                {getInitials(profile?.full_name || "Usuario")}
              </div>

              <div className="topbar-user-text">
                <strong>
                  {profile?.full_name || "Usuario"}
                </strong>

                <span>
                  Asesor
                </span>
              </div>

            </div>

          </div>

        </header>

        <div className="content-wrapper">

          {/* =================================================
              INICIO
          ================================================= */}

          {activeSection === "Inicio" && (
            <DashboardPage
              leads={leads}
              appointments={appointments}
              onNewLead={() =>
                setShowNewLead(true)
              }
              onGoToLeads={() =>
                handleNavigation("Mis interesados")
              }
              onGoToAgenda={() =>
                handleNavigation("Agenda")
              }
            />
          )}

          {/* =================================================
              MIS INTERESADOS
          ================================================= */}

          {activeSection ===
            "Mis interesados" && (

            <InterestedPage
              leads={filteredLeads}
              totalLeads={leads.length}
              search={search}
              setSearch={setSearch}
              statusFilter={statusFilter}
              setStatusFilter={
                setStatusFilter
              }
              onNewLead={() =>
                setShowNewLead(true)
              }
              onSelectLead={
                setSelectedLead
              }
            />

          )}

          {/* =================================================
              AGENDA
          ================================================= */}

          {activeSection === "Agenda" && (
            <AgendaPage
              appointments={appointments}
              onSelectAppointment={setSelectedAppointment}
              onNewAppointment={() =>
                setShowNewAppointment(true)
              }
            />
          )}

        </div>

      </main>

      {/* =====================================================
          NUEVO INTERESADO
      ===================================================== */}

      {showNewLead && (
        <NewLeadModal
          onClose={() =>
            setShowNewLead(false)
          }
          onSave={addLead}
        />
      )}

      {/* =====================================================
          DETALLE
      ===================================================== */}

      {selectedLead && (
        <LeadDetailModal
          lead={selectedLead}
          history={leadHistories[selectedLead.id] || []}
          onClose={() =>
            setSelectedLead(null)
          }
          onAddFollowUp={() =>
            setShowFollowUp(true)
          }
          onEdit={() => setShowEditLead(true)}
          appointments={appointments}
          onSelectAppointment={(appointment) => {
            setSelectedLead(null);
            setSelectedAppointment(appointment);
          }}
          onStatusChange={(status) =>
            updateLeadStatus(selectedLead.id, status)
          }
          maintenancePlan={maintenancePlans[selectedLead.id]}
          onPauseMaintenance={() => pauseMaintenanceAutomation(selectedLead.id)}
          onReactivateMaintenance={(date) => reactivateMaintenanceAutomation(selectedLead.id, date)}
        />
      )}

      {showEditLead && selectedLead && (
        <EditLeadModal
          lead={selectedLead}
          onClose={() => setShowEditLead(false)}
          onSave={updateLead}
        />
      )}

      {showFollowUp && selectedLead && (
        <FollowUpModal
          lead={selectedLead}
          onClose={() => setShowFollowUp(false)}
          onSave={(followUp) =>
            addLeadFollowUp(selectedLead.id, followUp)
          }
        />
      )}

      {showNewAppointment && (
        <NewAppointmentModal
          leads={leads}
          onClose={() => setShowNewAppointment(false)}
          onSave={addAppointment}
        />
      )}

      {selectedAppointment && (
        <AppointmentDetailModal
          appointment={selectedAppointment}
          history={appointmentHistories[selectedAppointment.id] || []}
          onClose={() =>
            setSelectedAppointment(null)
          }
          onUpdateStatus={updateAppointmentStatus}
          onEdit={() => setShowEditAppointment(true)}
        />
      )}

      {showEditAppointment && selectedAppointment && (
        <EditAppointmentModal
          appointment={selectedAppointment}
          leads={leads}
          onClose={() => setShowEditAppointment(false)}
          onSave={updateAppointment}
        />
      )}

    </div>
  );
}


