/* =====================================================
   ESTADOS
===================================================== */

function StatusBadge({ status }) {

  let className =
    "status-neutral";

  if (status === "Nuevo" || status === "Nada todavía") {
    className = "status-new";
  }

  if (
    status === "Confirmada" ||
    status === "Cita confirmada" ||
    status === "Con demo"
  ) {
    className =
      "status-confirmed";
  }

  if (
    status === "Pendiente" ||
    status === "Cita pendiente"
  ) {
    className =
      "status-pending";
  }

  if (status === "Contactado") {
    className =
      "status-contacted";
  }

  if (status === "Cita pospuesta" || status === "Pospuesta") {
    className =
      "status-postponed";
  }

  if (status === "Demo completada" || status === "Completada") {
    className = "status-completed";
  }

  if (status === "Cancelada") {
    className =
      "status-cancelled";
  }

  if (status === "Pendiente de capacitación") {
    className = "status-pending";
  }

  if (status === "Mantenimiento") {
    className = "status-maintenance";
  }

  if (status === "Completada") {
    className =
      "status-completed";
  }

  return (
    <span
      className={`status-badge ${className}`}
    >
      <i />
      {status}
    </span>
  );
}


/* =====================================================
   NUEVO INTERESADO
===================================================== */

function NewLeadModal({
  onClose,
  onSave,
}) {

  const [form, setForm] = useState({
    name: "",
    phone: "",
    occupation: "",
    address: "",
    observation: "",
  });

  const handleChange = (event) => {

    const {
      name,
      value,
    } = event.target;

    setForm((current) => ({
      ...current,
      [name]: value,
    }));
  };

  const handleSubmit = (event) => {

    event.preventDefault();

    if (
      !form.name ||
      !form.phone ||
      !form.occupation ||
      !form.address
    ) {
      return;
    }

    onSave(form);
  };

  return (

    <div
      className="modal-overlay"
      onMouseDown={onClose}
    >

      <div
        className="lead-modal"
        onMouseDown={(event) =>
          event.stopPropagation()
        }
      >

        <div className="modal-header">

          <div>

            <span className="section-eyebrow">
              CRM
            </span>

            <h3>
              Nuevo interesado
            </h3>

            <p>
              Registra manualmente una nueva
              persona interesada.
            </p>

          </div>


          <button
            className="modal-close"
            onClick={onClose}
            aria-label="Cerrar"
          >
            ×
          </button>

        </div>


        <form
          className="new-lead-form"
          onSubmit={handleSubmit}
        >

          <div className="form-row">

            <div className="modal-field">

              <label htmlFor="name">
                Nombre completo *
              </label>

              <input
                id="name"
                name="name"
                value={form.name}
                onChange={handleChange}
                placeholder="Ej. Juan Pérez"
                required
              />

            </div>


            <div className="modal-field">

              <label htmlFor="phone">
                Teléfono / WhatsApp *
              </label>

              <input
                id="phone"
                name="phone"
                value={form.phone}
                onChange={handleChange}
                placeholder="449 000 0000"
                inputMode="tel"
                required
              />

            </div>

          </div>


          <div className="form-row">

            <div className="modal-field">

              <label htmlFor="occupation">
                Ocupación *
              </label>

              <input
                id="occupation"
                name="occupation"
                value={form.occupation}
                onChange={handleChange}
                placeholder="Ej. Empresario"
                required
              />

            </div>


            <div className="modal-field">

              <label htmlFor="address">
                Domicilio *
              </label>

              <input
                id="address"
                name="address"
                value={form.address}
                onChange={handleChange}
                placeholder="Calle, número, colonia, ciudad"
                required
              />

            </div>

          </div>


          <div className="modal-field">

            <label htmlFor="observation">
              Observación
            </label>

            <textarea
              id="observation"
              name="observation"
              value={form.observation}
              onChange={handleChange}
              placeholder="Agrega información que pueda ayudarte a conocer o dar seguimiento al interesado..."
              rows="4"
            />

            <span className="field-helper">
              Este campo es opcional y sirve
              para tus notas de seguimiento
              inicial.
            </span>

          </div>


          <div className="modal-actions">

            <button
              type="button"
              className="secondary-button"
              onClick={onClose}
            >
              Cancelar
            </button>

            <button
              type="submit"
              className="primary-action"
            >
              Guardar interesado
            </button>

          </div>

        </form>

      </div>

    </div>
  );
}


