/* =====================================================
   AGENDA
===================================================== */

function AgendaPage({
  appointments,
  onSelectAppointment,
  onNewAppointment,
}) {
  const [agendaDate, setAgendaDate] =
    useState(new Date());

  const [agendaStatusFilter, setAgendaStatusFilter] =
    useState("Todos");

  const calendarDays = useMemo(
    () => getCalendarDays(agendaDate),
    [agendaDate]
  );

  const filteredAppointments = useMemo(() => {
    if (agendaStatusFilter === "Todos") {
      return appointments;
    }

    return appointments.filter(
      (appointment) =>
        appointment.status === agendaStatusFilter
    );
  }, [appointments, agendaStatusFilter]);

  const upcomingAppointments = useMemo(() => {
    const todayKey = formatDateKey(new Date());

    return appointments
      .filter(
        (appointment) =>
          appointment.date >= todayKey &&
          appointment.status !== "Cancelada"
      )
      .sort((a, b) =>
        `${a.date}${a.time}`.localeCompare(
          `${b.date}${b.time}`
        )
      );
  }, [appointments]);

  const goToPreviousMonth = () => {
    setAgendaDate(
      new Date(
        agendaDate.getFullYear(),
        agendaDate.getMonth() - 1,
        1
      )
    );
  };

  const goToNextMonth = () => {
    setAgendaDate(
      new Date(
        agendaDate.getFullYear(),
        agendaDate.getMonth() + 1,
        1
      )
    );
  };

  const goToToday = () => {
    setAgendaDate(new Date());
  };

  const getAppointmentsForDay = (day) => {
    const dayKey = formatDateKey(day);

    return filteredAppointments
      .filter(
        (appointment) =>
          appointment.date === dayKey
      )
      .sort((a, b) =>
        a.time.localeCompare(b.time)
      );
  };

  return (
    <section className="agenda-page">

      <div className="page-heading">

        <div>

          <span className="section-eyebrow">
            CALENDARIO
          </span>

          <h2>
            Mi agenda
          </h2>

          <p>
            Organiza tus demostraciones,
            seguimientos y llamadas.
          </p>

        </div>

        <div className="agenda-heading-actions">

          <button
            type="button"
            className="primary-action agenda-new-button"
            onClick={onNewAppointment}
          >
            + Nueva cita
          </button>

          <div className="agenda-summary">

            <div className="agenda-summary-item">
            <span>
              PRÓXIMAS CITAS
            </span>

            <strong>
              {upcomingAppointments.length}
            </strong>
          </div>

            <div className="agenda-summary-item">
              <span>
                CONFIRMADAS
              </span>

              <strong>
                {
                  appointments.filter(
                    (appointment) =>
                      appointment.status ===
                      "Confirmada"
                  ).length
                }
              </strong>
            </div>

          </div>

        </div>

      </div>


      <div className="agenda-layout">

        <div className="agenda-calendar-card">

          <div className="agenda-calendar-toolbar">

            <div className="agenda-calendar-title">

              <h3>
                {formatMonthTitle(agendaDate)}
              </h3>

              <button
                type="button"
                className="agenda-today-button"
                onClick={goToToday}
              >
                Hoy
              </button>

            </div>

            <div className="agenda-calendar-nav">

              <button
                type="button"
                className="agenda-nav-button"
                onClick={goToPreviousMonth}
                aria-label="Mes anterior"
              >
                ‹
              </button>

              <button
                type="button"
                className="agenda-nav-button"
                onClick={goToNextMonth}
                aria-label="Mes siguiente"
              >
                ›
              </button>

            </div>

          </div>


          <div className="agenda-weekdays">

            {[
              "DOM",
              "LUN",
              "MAR",
              "MIÉ",
              "JUE",
              "VIE",
              "SÁB",
            ].map((day) => (
              <div
                key={day}
                className="agenda-weekday"
              >
                {day}
              </div>
            ))}

          </div>


          <div className="agenda-calendar-grid">

            {calendarDays.map((day) => {

              const appointmentsForDay =
                getAppointmentsForDay(day);

              const isCurrentMonth =
                day.getMonth() ===
                  agendaDate.getMonth() &&
                day.getFullYear() ===
                  agendaDate.getFullYear();

              const isToday =
                formatDateKey(day) ===
                formatDateKey(new Date());

              return (
                <div
                  key={formatDateKey(day)}
                  className={`agenda-day ${
                    !isCurrentMonth
                      ? "other-month"
                      : ""
                  } ${
                    isToday ? "today" : ""
                  }`}
                >

                  <div className="agenda-day-number">
                    {day.getDate()}
                  </div>

                  <div className="agenda-events">

                    {appointmentsForDay
                      .slice(0, 3)
                      .map((appointment) => (
                        <button
                          type="button"
                          key={appointment.id}
                          className={`agenda-event ${appointmentStatusClass(
                            appointment.status
                          )}`}
                          onClick={() =>
                            onSelectAppointment(
                              appointment
                            )
                          }
                        >

                          <span className="agenda-event-time">
                            {appointment.time}
                          </span>

                          <span className="agenda-event-name">
                            {appointment.client}
                          </span>

                        </button>
                      ))}

                    {appointmentsForDay.length > 3 && (
                      <span className="agenda-more-events">
                        +{appointmentsForDay.length - 3} más
                      </span>
                    )}

                  </div>

                </div>
              );
            })}

          </div>

        </div>


        <aside className="agenda-upcoming-card">

          <div className="agenda-upcoming-header">

            <div>

              <span className="section-eyebrow">
                ACTIVIDAD
              </span>

              <h3>
                Próximas citas
              </h3>

            </div>

            <select
              className="agenda-filter"
              value={agendaStatusFilter}
              onChange={(event) =>
                setAgendaStatusFilter(
                  event.target.value
                )
              }
            >
              <option value="Todos">
                Todas
              </option>

              <option value="Pendiente">
                Pendientes
              </option>

              <option value="Confirmada">
                Confirmadas
              </option>

              <option value="Pospuesta">
                Pospuestas
              </option>

              <option value="Completada">
                Completadas
              </option>

              <option value="Cancelada">
                Canceladas
              </option>

            </select>

          </div>


          <div className="agenda-upcoming-list">

            {upcomingAppointments.length > 0 ? (

              upcomingAppointments.map(
                (appointment) => (
                  <button
                    type="button"
                    className="agenda-upcoming-item"
                    key={appointment.id}
                    onClick={() =>
                      onSelectAppointment(
                        appointment
                      )
                    }
                  >

                    <div className="agenda-upcoming-date">

                      <strong>
                        {formatDayNumber(
                          appointment.date
                        )}
                      </strong>

                      <span>
                        {formatDayName(
                          appointment.date
                        )}
                      </span>

                    </div>

                    <div className="agenda-upcoming-content">

                      <div>

                        <strong>
                          {appointment.client}
                        </strong>

                        <span>
                          {appointment.type}
                        </span>

                      </div>

                      <div className="agenda-upcoming-meta">

                        <span>
                          {appointment.time} –{" "}
                          {appointment.endTime}
                        </span>

                        <StatusBadge
                          status={
                            appointment.status
                          }
                        />

                      </div>

                    </div>

                  </button>
                )
              )

            ) : (

              <div className="empty-search agenda-empty">
                <div className="empty-search-icon">
                  □
                </div>

                <h3>
                  No hay citas próximas
                </h3>

                <p>
                  No existen citas que coincidan
                  con el filtro seleccionado.
                </p>
              </div>

            )}

          </div>

        </aside>

      </div>

    </section>
  );
}


