function NewAppointmentModal({
  leads,
  onClose,
  onSave,
}) {
  const [form, setForm] = useState({
    leadId: String(leads[0]?.id || ""),
    client: leads[0]?.name || "",
    type: "Demostración",
    date: formatDateKey(new Date()),
    time: "10:00",
    endTime: "11:00",
    location: "Aguascalientes",
    notes: "",
  });

  const [error, setError] = useState("");

  const handleChange = (event) => {
    const { name, value } = event.target;

    if (name === "leadId") {
      const selectedLead = leads.find(
        (lead) => String(lead.id) === value
      );

      setForm((current) => ({
        ...current,
        leadId: value,
        client: selectedLead?.name || "",
      }));
    } else {
      setForm((current) => ({
        ...current,
        [name]: value,
      }));
    }

    setError("");
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    if (
      !form.leadId ||
      !form.client ||
      !form.date ||
      !form.time ||
      !form.endTime
    ) {
      setError(
        "Completa los campos obligatorios para guardar la cita."
      );
      return;
    }

    if (form.endTime <= form.time) {
      setError(
        "La hora de término debe ser posterior a la hora de inicio."
      );
      return;
    }

    onSave({
      ...form,
      status: "Pendiente",
    });
  };

  return (
    <div
      className="modal-overlay"
      onMouseDown={onClose}
    >
      <div
        className="new-appointment-modal"
        onMouseDown={(event) =>
          event.stopPropagation()
        }
      >
        <div className="modal-header">
          <div>
            <span className="section-eyebrow">
              AGENDA
            </span>

            <h3>
              Nueva cita
            </h3>

            <p>
              Agenda una demostración, seguimiento, capacitación o mantenimiento con uno de tus interesados.
            </p>
          </div>

          <button
            className="modal-close"
            onClick={onClose}
            aria-label="Cerrar"
          >
            ×
          </button>
        </div>

        <form
          className="new-appointment-form"
          onSubmit={handleSubmit}
        >
          <div className="form-row">
            <div className="modal-field">
              <label htmlFor="appointment-client">
                Interesado *
              </label>

              <select
                id="appointment-client"
                name="leadId"
                value={form.leadId}
                onChange={handleChange}
                required
              >
                {leads.map((lead) => (
                  <option
                    key={lead.id}
                    value={lead.id}
                  >
                    {lead.name}
                  </option>
                ))}
              </select>
            </div>

            <div className="modal-field">
              <label htmlFor="appointment-type">
                Tipo de cita *
              </label>

              <select
                id="appointment-type"
                name="type"
                value={form.type}
                onChange={handleChange}
                required
              >
                <option value="Demostración">
                  Demostración
                </option>
                <option value="Seguimiento">
                  Seguimiento
                </option>
                <option value="Primera llamada">
                  Primera llamada
                </option>
                <option value="Capacitación">
                  Capacitación
                </option>
                <option value="Mantenimiento de equipo">
                  Mantenimiento de equipo
                </option>
                <option value="Otro">
                  Otro
                </option>
              </select>
            </div>
          </div>

          <div className="form-row">
            <div className="modal-field">
              <label htmlFor="appointment-date">
                Fecha *
              </label>

              <input
                id="appointment-date"
                name="date"
                type="date"
                value={form.date}
                onChange={handleChange}
                required
              />
            </div>

            <div className="modal-field">
              <label htmlFor="appointment-location">
                Ubicación
              </label>

              <input
                id="appointment-location"
                name="location"
                value={form.location}
                onChange={handleChange}
                placeholder="Ej. Aguascalientes"
              />
            </div>
          </div>

          <div className="form-row">
            <div className="modal-field">
              <label htmlFor="appointment-time">
                Hora de inicio *
              </label>

              <input
                id="appointment-time"
                name="time"
                type="time"
                value={form.time}
                onChange={handleChange}
                required
              />
            </div>

            <div className="modal-field">
              <label htmlFor="appointment-end-time">
                Hora de término *
              </label>

              <input
                id="appointment-end-time"
                name="endTime"
                type="time"
                value={form.endTime}
                onChange={handleChange}
                required
              />
            </div>
          </div>

          <div className="modal-field">
            <label htmlFor="appointment-notes">
              Observaciones / notas
            </label>

            <textarea
              id="appointment-notes"
              name="notes"
              value={form.notes}
              onChange={handleChange}
              placeholder="Agrega cualquier observación, seguimiento, próxima llamada o información importante..."
              rows="4"
            />
          </div>

          {error && (
            <div className="appointment-form-error">
              {error}
            </div>
          )}

          <div className="modal-actions">
            <button
              type="button"
              className="secondary-button"
              onClick={onClose}
            >
              Cancelar
            </button>

            <button
              type="submit"
              className="primary-action"
            >
              Guardar cita
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}


