function EditAppointmentModal({
  appointment,
  leads,
  onClose,
  onSave,
}) {
  const [form, setForm] = useState({
    leadId: String(appointment.leadId || leads.find((lead) => lead.name === appointment.client)?.id || leads[0]?.id || ""),
    client: appointment.client || leads[0]?.name || "",
    type: appointment.type || "Demostración",
    date: appointment.date || formatDateKey(new Date()),
    time: appointment.time || "10:00",
    endTime: appointment.endTime || "11:00",
    location: appointment.location || "",
    notes: appointment.notes || "",
  });

  const [error, setError] = useState("");

  const handleChange = (event) => {
    const { name, value } = event.target;

    if (name === "leadId") {
      const selectedLead = leads.find(
        (lead) => String(lead.id) === value
      );

      setForm((current) => ({
        ...current,
        leadId: value,
        client: selectedLead?.name || "",
      }));
    } else {
      setForm((current) => ({
        ...current,
        [name]: value,
      }));
    }

    setError("");
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    if (
      !form.leadId ||
      !form.client ||
      !form.date ||
      !form.time ||
      !form.endTime
    ) {
      setError(
        "Completa los campos obligatorios para guardar los cambios."
      );
      return;
    }

    if (form.endTime <= form.time) {
      setError(
        "La hora de término debe ser posterior a la hora de inicio."
      );
      return;
    }

    onSave(appointment.id, {
      ...form,
      status: appointment.status,
    });
  };

  return (
    <div
      className="modal-overlay edit-appointment-overlay"
      onMouseDown={onClose}
    >
      <div
        className="new-appointment-modal edit-appointment-modal"
        onMouseDown={(event) => event.stopPropagation()}
      >
        <div className="modal-header">
          <div>
            <span className="section-eyebrow">
              AGENDA
            </span>

            <h3>
              Actualizar cita
            </h3>

            <p>
              Actualiza la fecha, horario, tipo, ubicación y observaciones de la cita.
            </p>
          </div>

          <button
            className="modal-close"
            onClick={onClose}
            aria-label="Cerrar"
          >
            ×
          </button>
        </div>

        <form
          className="new-appointment-form edit-appointment-form"
          onSubmit={handleSubmit}
        >
          <div className="form-row">
            <div className="modal-field">
              <label htmlFor="edit-appointment-client">
                Interesado *
              </label>

              <select
                id="edit-appointment-client"
                name="leadId"
                value={form.leadId}
                onChange={handleChange}
                required
              >
                {leads.map((lead) => (
                  <option
                    key={lead.id}
                    value={lead.id}
                  >
                    {lead.name}
                  </option>
                ))}
              </select>
            </div>

            <div className="modal-field">
              <label htmlFor="edit-appointment-type">
                Tipo de cita *
              </label>

              <select
                id="edit-appointment-type"
                name="type"
                value={form.type}
                onChange={handleChange}
                required
              >
                <option value="Demostración">
                  Demostración
                </option>
                <option value="Seguimiento">
                  Seguimiento
                </option>
                <option value="Primera llamada">
                  Primera llamada
                </option>
                <option value="Capacitación">
                  Capacitación
                </option>
                <option value="Mantenimiento de equipo">
                  Mantenimiento de equipo
                </option>
                <option value="Otro">
                  Otro
                </option>
              </select>
            </div>
          </div>

          <div className="form-row">
            <div className="modal-field">
              <label htmlFor="edit-appointment-date">
                Fecha *
              </label>

              <input
                id="edit-appointment-date"
                name="date"
                type="date"
                value={form.date}
                onChange={handleChange}
                required
              />
            </div>

            <div className="modal-field">
              <label htmlFor="edit-appointment-location">
                Ubicación
              </label>

              <input
                id="edit-appointment-location"
                name="location"
                value={form.location}
                onChange={handleChange}
                placeholder="Ej. Aguascalientes"
              />
            </div>
          </div>

          <div className="form-row">
            <div className="modal-field">
              <label htmlFor="edit-appointment-time">
                Hora de inicio *
              </label>

              <input
                id="edit-appointment-time"
                name="time"
                type="time"
                value={form.time}
                onChange={handleChange}
                required
              />
            </div>

            <div className="modal-field">
              <label htmlFor="edit-appointment-end-time">
                Hora de término *
              </label>

              <input
                id="edit-appointment-end-time"
                name="endTime"
                type="time"
                value={form.endTime}
                onChange={handleChange}
                required
              />
            </div>
          </div>

          <div className="modal-field">
            <label htmlFor="edit-appointment-notes">
              Observaciones / notas
            </label>

            <textarea
              id="edit-appointment-notes"
              name="notes"
              value={form.notes}
              onChange={handleChange}
              placeholder="Agrega cualquier observación, seguimiento, próxima llamada o información importante..."
              rows="4"
            />
          </div>

          {error && (
            <div className="appointment-form-error">
              {error}
            </div>
          )}

          <div className="modal-actions">
            <button
              type="button"
              className="secondary-button"
              onClick={onClose}
            >
              Cancelar
            </button>

            <button
              type="submit"
              className="primary-action"
            >
              Guardar cambios
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}


