/* =====================================================
   FUNCIONES DE AGENDA
===================================================== */

function addMonthsToDateKey(dateKey, months) {
  const [year, month, day] = dateKey.split("-").map(Number);
  const date = new Date(year, month - 1, day);
  date.setMonth(date.getMonth() + months);

  // Evita que fechas como 31 de enero salten al mes siguiente
  // por no existir ese mismo día en el mes destino.
  if (date.getDate() !== day) {
    date.setDate(0);
  }

  return formatDateKey(date);
}

function addDaysToDateKey(dateKey, days) {
  const [year, month, day] = dateKey.split("-").map(Number);
  const date = new Date(year, month - 1, day);
  date.setDate(date.getDate() + days);
  return formatDateKey(date);
}


function formatDateLabel(date) {
  return date.toLocaleDateString("es-MX", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

function formatTimeLabel(date) {
  return date.toLocaleTimeString("es-MX", {
    hour: "numeric",
    minute: "2-digit",
  });
}

function MaintenancePanel({ lead, plan, onPause, onReactivate }) {
  const [activationDate, setActivationDate] = useState(plan?.activatedDate || formatDateKey(new Date()));
  const active = plan?.active !== false;
  const nextDate = plan?.nextDate;

  return (
    <div className="maintenance-panel">
      <div className="maintenance-panel-header">
        <div>
          <span className="section-eyebrow">MANTENIMIENTO</span>
          <h4>Seguimiento de mantenimiento</h4>
          <p>Controla el ciclo periódico de este cliente sin perder la posibilidad de gestionarlo manualmente.</p>
        </div>
        <span className={`maintenance-automation-badge ${active ? "is-active" : "is-paused"}`}>
          {active ? "Automatización activa" : "Automatización pausada"}
        </span>
      </div>

      <div className="maintenance-panel-grid">
        <div className="maintenance-panel-item">
          <span>PRÓXIMO MANTENIMIENTO</span>
          <strong>{nextDate ? formatFullDate(nextDate) : "Sin fecha programada"}</strong>
        </div>
        <div className="maintenance-panel-item">
          <span>CICLO</span>
          <strong>Cada 3 meses</strong>
        </div>
      </div>

      {active ? (
        <button type="button" className="secondary-button maintenance-control-button" onClick={onPause}>
          Pausar automatización
        </button>
      ) : (
        <div className="maintenance-reactivate">
          <div className="modal-field">
            <label htmlFor={`reactivate-maintenance-${lead.id}`}>Reactivar desde</label>
            <input
              id={`reactivate-maintenance-${lead.id}`}
              type="date"
              value={activationDate}
              onChange={(event) => setActivationDate(event.target.value)}
            />
            <span className="field-helper">El próximo mantenimiento se calculará 3 meses después de esta fecha.</span>
          </div>
          <button type="button" className="primary-action" onClick={() => onReactivate(activationDate)}>
            Reactivar mantenimiento
          </button>
        </div>
      )}
    </div>
  );
}

function formatDateKey(date) {
  const year = date.getFullYear();

  const month = String(
    date.getMonth() + 1
  ).padStart(2, "0");

  const day = String(
    date.getDate()
  ).padStart(2, "0");

  return `${year}-${month}-${day}`;
}


function formatMonthTitle(date) {
  const value =
    date.toLocaleDateString(
      "es-MX",
      {
        month: "long",
        year: "numeric",
      }
    );

  return (
    value.charAt(0).toUpperCase() +
    value.slice(1)
  );
}


function formatFullDate(dateKey) {
  const [
    year,
    month,
    day,
  ] = dateKey.split("-").map(Number);

  const value =
    new Date(
      year,
      month - 1,
      day
    ).toLocaleDateString(
      "es-MX",
      {
        weekday: "long",
        day: "numeric",
        month: "long",
        year: "numeric",
      }
    );

  return (
    value.charAt(0).toUpperCase() +
    value.slice(1)
  );
}


function formatDayNumber(dateKey) {
  const [
    year,
    month,
    day,
  ] = dateKey.split("-").map(Number);

  return new Date(
    year,
    month - 1,
    day
  ).getDate();
}


function formatDayName(dateKey) {
  const [
    year,
    month,
    day,
  ] = dateKey.split("-").map(Number);

  return new Date(
    year,
    month - 1,
    day
  ).toLocaleDateString(
    "es-MX",
    {
      weekday: "short",
    }
  );
}


function getCalendarDays(date) {
  const firstDay =
    new Date(
      date.getFullYear(),
      date.getMonth(),
      1
    );

  const startDay =
    firstDay.getDay();

  const calendarStart =
    new Date(
      date.getFullYear(),
      date.getMonth(),
      1 - startDay
    );

  return Array.from(
    { length: 42 },
    (_, index) =>
      new Date(
        calendarStart.getFullYear(),
        calendarStart.getMonth(),
        calendarStart.getDate() + index
      )
  );
}


function getInitials(name) {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) =>
      part.charAt(0).toUpperCase()
    )
    .join("");
}


function appointmentStatusClass(status) {
  const classes = {
    Pendiente: "event-pendiente",
    Confirmada: "event-confirmada",
    Pospuesta: "event-pospuesta",
    Cancelada: "event-cancelada",
    Completada: "event-completada",
  };

  return (
    classes[status] ||
    "event-pendiente"
  );
}


export default App;